from std.sync import Atomic

struct Stats:
    hits: Atomic[int]
    names: Array[String]          # owns heap memory, so [CT-5]'s third bullet applies: `s` is a `ref Stats` into constant data

fn fresh() -> Stats:
    return Stats(hits=Atomic(0), names=[String("a")])

fn main():
    s = comptime(fresh())
    s.hits.fetch_add(1)           # <- an atomic read-modify-write into read-only memory: a fault in safe code, or, if the image is writable, one object shared by every evaluation of this line

# the same with `lock: Mutex[int]` and `with g = s.lock:`, and with a class object whose `@cached fn area()` stores its result in the object through `ref`

fn first_negative(xs: Span[i32]) -> Option[int]:
    for i in 0..xs.len():
        y = xs[i] * 4            # overflows at i = 2 when xs[2] == i32.MAX; computed wrapping inside the group, so `y` is negative
        if y < 0:
            return Some(i)       # <- leaves the group before its end: the accumulated overflow bit is never tested, and the function returns a wrong answer with no panic
    return None

# the same with `break`; and with `for j in 0..y:` as an inner loop, which runs 2^31 steps on the wrapped value before the group ends

